// rsuTrend_Y.cpp : Defines the entry point for the DLL application.//#include "stdafx.h"#include "rsuTrend_H.h"#include <TrendsSup.h>#include <BaseType_.h>#include <err.h>#include <stdlib.h>#include <Names.h>#include <UtilsH.h>#ifdef _MANAGED#pragma managed(push, off)#endifBOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){	switch (ul_reason_for_call)	{	case DLL_PROCESS_ATTACH:	case DLL_THREAD_ATTACH:	case DLL_THREAD_DETACH:	case DLL_PROCESS_DETACH:		break;	}    return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endifstruct SAddTrend {  char name[16];  SValueDef* def[id_AcyMax-id_AcyMin+1];};SAddTrend list[] ={  { "PV"  },  { "SP"  },  { "OP"  },  { "PVP" },  { "SPP" },  { "C(1)" },  { "C(2)" },  { "C(3)" },  { "C(4)" },  { "C(5)" },  { "C(6)" },  { "C(7)" },  { "C(8)" },  { "C[1]" },  { "C[2]" },  { "C[3]" },  { "C[4]" },  { "C[5]" },  { "C[6]" },  { "C[7]" },  { "C[8]" },};extern "C" __declspec(dllexport) int TrendInfoPoint(DWORD type, LPCSTR pObjName, CBase* pBase, int fcsNumber, int cInfs, STrendPointInfo *pInfs ){  DWORD N = pBase->ID_CLASS;  if( !IsAcy(N) )    return 0;  static bool bInited = false;  if( !bInited )  {    bInited = true;    for ( UINT n = 0; n < _countof(list); n++ )    {      for ( UINT m = id_AcyMin; m < id_AcyMax; m++ )      {        list[n].def[m-id_AcyMin] = NameToValueH( m, list[n].name );      }    }  }  int c = 0;  for ( UINT n = 0; n < _countof(list); n++ )  {    if( list[n].def[N-id_AcyMin] == NULL )      continue;    if( c>= cInfs )      break;    STrendPointInfo &obj = pInfs[c];    obj.eValType = list[n].def[N-id_AcyMin]->eVal;    obj.dwID = GetID( pObjName, list[n].name, fcsNumber );    ASS( obj.dwID );    obj.pAddr = (BYTE*)(((BYTE*)pBase)+list[n].def[N-id_AcyMin]->dwShift);    obj.pszSufName = list[n].name;    c++;  }  return c;}